    make_padding(bottom_blob, bottom_blob_bordered, opt);
    if (bottom_blob_bordered.empty())
        return -100;

    int w = bottom_blob_bordered.w;
    int h = bottom_blob_bordered.h;

    const int kernel_extent_w = dilation_w * (kernel_w - 1) + 1;
    const int kernel_extent_h = dilation_h * (kernel_h - 1) + 1;

    int outw = (w - kernel_extent_w) / stride_w + 1;
    int outh = (h - kernel_extent_h) / stride_h + 1;

    size_t elemsize = bottom_blob_bordered.elemsize;

    top_blob.create(outw, outh, num_output, elemsize, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    // If elempack==1 or dilation!=1 use scalar fallback
    if (bottom_blob_bordered.elempack == 1 || dilation_w != 1 || dilation_h != 1)
    {
        return convolution_scalar(bottom_blob_bordered, top_blob, weight_data, bias_data,
                                  kernel_w, kernel_h, stride_w, stride_h, dilation_w, dilation_h,
                                  activation_type, activation_params, opt);
    }

    // RVV optimized path via im2col + sgemm for general kernel
    const int maxk = kernel_w * kernel_h;
    const int inch = bottom_blob_bordered.c;

    // build im2col buffer
    Mat bottom_im2col(outw * outh, maxk, inch, 4u, 1, opt.workspace_allocator);
    if (bottom_im2col.empty())
        return -100;

    // fill im2col
    {
        std::vector<int> _space_ofs(maxk);
        int* space_ofs = &_space_ofs[0];
        {
            int p1 = 0;
            int p2 = 0;
            int gap = w * dilation_h - kernel_w * dilation_w;
            for (int i = 0; i < kernel_h; i++)
            {
                for (int j = 0; j < kernel_w; j++)
                {
                    space_ofs[p1] = p2;
                    p1++;
                    p2 += dilation_w;
                }
                p2 += gap;
            }
        }

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < inch; q++)
        {
            const Mat img = bottom_blob_bordered.channel(q);
            float* im2colptr = bottom_im2col.channel(q);

            for (int i = 0; i < outh; i++)
            {
                for (int j = 0; j < outw; j++)
                {
                    const float* sptr = img.row(i * stride_h) + j * stride_w;
                    for (int k = 0; k < maxk; k++)
                    {
                        im2colptr[k] = sptr[space_ofs[k]];
                    }
                    im2colptr += maxk;
                }
            }
        }
    }

    // sgemm
    im2col_sgemm_rvv(bottom_im2col, top_blob, weight_data.reshape(maxk, inch, num_output), bias_data, opt);

    // activation
    if (activation_type != 0)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int p = 0; p < num_output; p++)
        {
            float* outptr = top_blob.channel(p);
            int total = outw * outh;
#if __riscv_vector
            int packn = rvv_packn_e32();
            for (int i = 0; i < total; i += packn)
            {
                size_t vl = __riscv_vsetvl_e32m8(std::min(packn, total - i));
                vfloat32m8_t v = __riscv_vle32_v_f32m8(outptr + i, vl);
                v = activation_ps(v, activation_type, activation_params, vl);
                __riscv_vse32_v_f32m8(outptr + i, v, vl);
            }
#else
            for (int i = 0; i < total; i++)
                outptr[i] = activation_ss(outptr[i], activation_type, activation_params);
#endif
        }
    }

    return 0;
}

int Convolution_riscv::forward(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    // dynamic weight path fallback to generic
    return Convolution::forward(bottom_blobs, top_blobs, opt);
}

