                // apply activation via rvv vector on scalar lane
                vfloat32m1_t vsum = __riscv_vfmv_v_f_f32m1(sum, 1);
                vsum = activation_ps(vsum, activation_type, activation_params, 1);
                sum = __riscv_vfmv_f_s_f32m1_f32(vsum);
