// RVV optimized im2col + sgemm for packn
static void im2col_sgemm_rvv(const Mat& bottom_im2col, Mat& top_blob, const Mat& kernel, const Mat& _bias, const Option& opt)
{
    const int size = bottom_im2col.w;
    const int maxk = bottom_im2col.h;
    const int inch = bottom_im2col.c;
    const int outch = top_blob.c;

    const float* bias = _bias;

    Mat tmp;
    if (size >= 4)
        tmp.create(4 * maxk, inch, size / 4 + size % 4, 4u, 1, opt.workspace_allocator);
    else
        tmp.create(maxk, inch, size, 4u, 1, opt.workspace_allocator);

    // permute im2col to contiguous blocks of 4
    {
        int nn_size = size / 4;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int ii = 0; ii < nn_size; ii++)
        {
            int i = ii * 4;
            float* tmpptr = tmp.channel(i / 4);

            for (int q = 0; q < inch; q++)
            {
                const float* img0 = (const float*)bottom_im2col.channel(q) + i;
                for (int k = 0; k < maxk; k++)
                {
#if __riscv_vector
                    // load 4 floats and store
                    size_t vl = __riscv_vsetvl_e32m1(4);
                    vfloat32m1_t v = __riscv_vle32_v_f32m1(img0, vl);
                    __riscv_vse32_v_f32m1(tmpptr, v, vl);
#else
                    tmpptr[0] = img0[0];
                    tmpptr[1] = img0[1];
                    tmpptr[2] = img0[2];
                    tmpptr[3] = img0[3];
#endif
                    img0 += size;
                    tmpptr += 4;
                }
            }
        }

        int remain_size_start = nn_size * 4;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = remain_size_start; i < size; i++)
        {
            float* tmpptr = tmp.channel(i / 4 + i % 4);
            for (int q = 0; q < inch; q++)
            {
                const float* img0 = (const float*)bottom_im2col.channel(q) + i;
                for (int k = 0; k < maxk; k++)
                {
                    tmpptr[0] = img0[0];
                    img0 += size;
                    tmpptr += 1;
                }
            }
        }
    }

    // compute output channels in blocks
    #pragma omp parallel for num_threads(opt.num_threads)
    for (int p = 0; p < outch; p++)
    {
        float* outptr = top_blob.channel(p);
        const float* biasptr = bias ? bias + p : nullptr;

        int i = 0;
        for (; i + 3 < size; i += 4)
        {
            const float* tmpptr = tmp.channel(i / 4);
            const float* kptr = kernel.channel(p);
            int nn = inch * maxk;

#if __riscv_vector
            size_t vl = __riscv_vsetvl_e32m8(4 * rvv_packn_e32());
            vfloat32m8_t vsum = __riscv_vfmv_v_f_f32m8(biasptr ? *biasptr : 0.f, vl);
            for (int q = 0; q < nn; q++)
            {
                vfloat32m8_t vval = __riscv_vfmv_v_f_f32m8(tmpptr[0], vl);
                vfloat32m8_t vwt = __riscv_vfmv_v_f_f32m8(kptr[0], vl);
                vsum = __riscv_vfmadd_vv_f32m8(vval, vwt, vsum, vl);
                tmpptr += 4;
                kptr += 1;
            }
            // horizontal reduce
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.f, 1);
            vfloat32m1_t vres = __riscv_vfredusum_vs_f32m8_f32m1(vsum, vzero, vl);
            float sum = __riscv_vfmv_f_s_f32m1_f32(vres);
            // activation and store
            vfloat32m1_t vs = __riscv_vfmv_v_f_f32m1(sum, 1);
            vs = activation_ps(vs, 1, Mat(), 1);
            outptr[0] = __riscv_vfmv_f_s_f32m1_f32(vs);
            outptr += 4;
#else
            float sum = biasptr ? *biasptr : 0.f;
            for (int q = 0; q < nn; q++)
            {
                sum += tmpptr[0] * kptr[0];
                tmpptr += 4;
                kptr += 1;
            }
            outptr[0] = sum;
            outptr += 4;
#endif
        }
        for (; i < size; i++)
        {
            const float* tmpptr = tmp.channel(i / 4 + i % 4);
            const float* kptr = kernel.channel(p);
            int nn = inch * maxk;
            float sum = biasptr ? *biasptr : 0.f;
            for (int q = 0; q < nn; q++)
            {
                sum += tmpptr[0] * kptr[0];
                tmpptr++;
                kptr++;
            }
            outptr[0] = sum;
            outptr++;
        }
    }
}

int Convolution_riscv::forward(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    // Quantized int8 path can fallback to generic Convolution::forward_int8
#if NCNN_INT8
    if (opt.use_int8_inference && weight_data.elemsize == (size_t)1u)
    {
        return Convolution::forward_int8(bottom_blob, top_blob, opt);
    }
#endif

    // Handle flattened blob via InnerProduct as in generic path
    if (bottom_blob.dims == 1 && kernel_w == 1 && kernel_h == 1)
    {
        return Convolution::forward(bottom_blob, top_blob, opt);
    }

    Mat bottom_blob_bordered;
    make_padding(bottom_blob, bottom_blob_bordered, opt);
    if (bottom_blob_bordered.empty())
        return -100;

    int w = bottom_blob_bordered.w;
    int h = bottom_blob_bordered.h;

    const int kernel_extent_w = dilation_w * (kernel_w - 1) + 1;
    const int kernel_extent_h = dilation_h * (kernel_h - 1) + 1;

    int outw = (w - kernel_extent_w) / stride_w + 1;
    int outh = (h - kernel_extent_h) / stride_h + 1;

    size_t elemsize = bottom_blob_bordered.elemsize;

    top_blob.create(outw, outh, num_output, elemsize, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    // If elempack==1 or dilation!=1 use scalar fallback
    if (bottom_blob_bordered.elempack == 1 || dilation_w != 1 || dilation_h != 1)
    {
        return convolution_scalar(bottom_blob_bordered, top_blob, weight_data, bias_data,
                                  kernel_w, kernel_h, stride_w, stride_h, dilation_w, dilation_h,
                                  activation_type, activation_params, opt);
    }

    // RVV optimized path via im2col + sgemm for general kernel
    const int maxk = kernel_w * kernel_h;
    const int inch = bottom_blob_bordered.c;

    // build im2col buffer
    Mat bottom_im2col(outw * outh, maxk, inch, 4u, 1, opt.workspace_allocator);
    if (bottom_im2col.empty())
        return -100;

    // fill im2col
    {
        std::vector<int> _space_ofs(maxk);
        int* space_ofs = &_space_ofs[0];
        {
            int p1 = 0;
            int p2 = 0;
            int gap = w * dilation_h - kernel_w * dilation_w;
            for (int i = 0; i < kernel_h; i++)
            {
                for (int j = 0; j < kernel_w; j++)
                {
                    space_ofs[p1] = p2;
                    p1++;
                    p2 += dilation_w;
                }
                p2 += gap;
            }
        }

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < inch; q++)
        {
            const Mat img = bottom_blob_bordered.channel(q);
            float* im2colptr = bottom_im2col.channel(q);

            for (int i = 0; i < outh; i++)
            {
                for (int j = 0; j < outw; j++)
                {
                    const float* sptr = img.row(i * stride_h) + j * stride_w;
                    for (int k = 0; k < maxk; k++)
                    {
                        im2colptr[k] = sptr[space_ofs[k]];
                    }
                    im2colptr += maxk;
                }
            }
        }
    }

    // sgemm
    im2col_sgemm_rvv(bottom_im2col, top_blob, weight_data.reshape(maxk, inch, num_output), bias_data, opt);

    // activation
    if (activation_type != 0)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int p = 0; p < num_output; p++)
        {
            float* outptr = top_blob.channel(p);
            int total = outw * outh;
#if __riscv_vector
            int packn = rvv_packn_e32();
            for (int i = 0; i < total; i += packn)
            {
                size_t vl = __riscv_vsetvl_e32m8(std::min(packn, total - i));
                vfloat32m8_t v = __riscv_vle32_v_f32m8(outptr + i, vl);
                v = activation_ps(v, activation_type, activation_params, vl);
                __riscv_vse32_v_f32m8(outptr + i, v, vl);
            }
#else
            for (int i = 0; i < total; i++)
                outptr[i] = activation_ss(outptr[i], activation_type, activation_params);
#endif
        }
    }

    return 0;
}

int Convolution_riscv::forward(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    // dynamic weight path fallback to generic
    return Convolution::forward(bottom_blobs, top_blobs, opt);
}

