           || test_convolution(10, 9, 4, 140, 3, 1, 1, 0, 0)
           || test_convolution(9, 10, 6, 160, 3, 1, 1, 0, 0);
}

int main()
{
    SRAND(7767517);

    return test_convolution_0() || test_convolution_1();
}

